-- Change feed: every write bumps its table's version, from any process
-- (the app or the MCP server). The app polls this table and tells the UI
-- which tables changed, so every view stays live without a reload.
CREATE TABLE data_change (
    tbl     TEXT PRIMARY KEY,
    version INTEGER NOT NULL DEFAULT 0
);
INSERT INTO data_change (tbl) VALUES ('profile');
CREATE TRIGGER profile_insert_change AFTER INSERT ON profile BEGIN UPDATE data_change SET version = version + 1 WHERE tbl = 'profile'; END;
CREATE TRIGGER profile_update_change AFTER UPDATE ON profile BEGIN UPDATE data_change SET version = version + 1 WHERE tbl = 'profile'; END;
CREATE TRIGGER profile_delete_change AFTER DELETE ON profile BEGIN UPDATE data_change SET version = version + 1 WHERE tbl = 'profile'; END;
